name: Harness Drift Report

on:
  schedule:
    # Run every Monday at 09:00 UTC
    - cron: "0 9 * * 1"
  workflow_dispatch:
    inputs:
      force:
        description: "Force run even if no changes detected"
        required: false
        default: "false"

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  drift-report:
    name: Generate Drift Report
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: "20"
          cache: "npm"

      - name: Install dependencies
        run: npm ci

      - name: Run Drift Check
        id: drift
        run: |
          # Run the drift check script. 
          # Assuming the script exits 0 on success (no new drift) or non-zero on failure.
          # We capture the output to use in the report.
          npm run drift:check > drift-report.txt 2>&1 || true

          # Check if there are any tracked debt entries or new violations
          if grep -q "tracked-debt" drift-report.txt || grep -q "violation" drift-report.txt; then
            echo "has_drift=true" >> $GITHUB_OUTPUT
          else
            echo "has_drift=false" >> $GITHUB_OUTPUT
          fi

      - name: Create or Update Drift Report Issue
        if: always()
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const issueTitle = '📊 Weekly Harness Drift Report';
            const label = 'harness-drift';

            // Read the drift report output
            let reportContent = '';
            try {
              reportContent = fs.readFileSync('drift-report.txt', 'utf8');
            } catch (e) {
              reportContent = 'No drift report generated.';
            }

            // Format the body
            const body = `## Harness Drift Report

**Date:** ${new Date().toISOString().split('T')[0]}
**Status:** ${{ steps.drift.outputs.has_drift === 'true' ? '⚠️ Drift Detected' : '✅ Clean' }}

### Details

\`\`\`
${reportContent}
\`\`\`

### Action Items

- [ ] Review any new violations.
- [ ] Address tracked debt items if possible.
- [ ] Update harness rules if false positives are detected.

---
*This issue is automatically generated by the Harness Drift Report workflow.*
`;

            // Find existing issue
            const existingIssues = await github.rest.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              labels: label,
            });

            let issueNumber;
            if (existingIssues.data.length > 0) {
              issueNumber = existingIssues.data[0].number;
              await github.rest.issues.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                body: body,
              });
              console.log(`Updated issue #${issueNumber}`);
            } else {
              const newIssue = await github.rest.issues.create({
                owner: context.repo.owner,
                repo: context.repo.repo,
                title: issueTitle,
                body: body,
                labels: [label],
              });
              issueNumber = newIssue.data.number;
              console.log(`Created new issue #${issueNumber}`);
            }
```

